sys_script_include.script:
var TrelloHandler = Class.create();
TrelloHandler.prototype = {
    initialize: function() {
        this.cardService = new CardService();
    },

    handle: function(payload) {
        var actionType = payload.u_event_type_translation_key;

        switch (actionType) {
            case "action_archived_card":
                return this.cardService.archiveCard(payload.u_trello_card_id);
                //break;
			case "action_create_card":
				return this.cardService.createCard(payload);
            default:
                throw new Error("Unsupported Trello event");
        }
    },
    type: 'TrelloHandler'
};
